27	type (
28		// lexer is a utility which can get values, token by
29		// token, from a Reader. A token is a word, and tokens
30		// are separated by whitespace. A word can be enclosed
31		// in quotes if it contains whitespace.
32		lexer struct {
33			reader       *bufio.Reader
34			token        Token
35			line         int
36			skippedLines int
37		}
38	
39		// Token represents a single parsable unit.
