481	// GetContext gets the value of a key in the context map.
482	func (d *Dispenser) GetContext(key string) any {
483		if d.context == nil {
484			return nil
485		}
486		return d.context[key]
487	}
488	
489	// GetContextString gets the value of a key in the context map
490	// as a string, or an empty string if the key does not exist.
491	func (d *Dispenser) GetContextString(key string) string {
492		if d.context == nil {
493			return ""
494		}
495		if val, ok := d.context[key].(string); ok {
496			return val
497		}
498		return ""
499	}
500	
501	// isNewLine determines whether the current token is on a different
502	// line (higher line number) than the previous token. It handles imported
503	// tokens correctly. If there isn't a previous token, it returns true.
504	func (d *Dispenser) isNewLine() bool {
505		if d.cursor < 1 {
506			return true
507		}
508		if d.cursor > len(d.tokens)-1 {
509			return false
510		}
511	
512		prev := d.tokens[d.cursor-1]
513		curr := d.tokens[d.cursor]
514		return isNextOnNewLine(prev, curr)
515	}
