package caddyfile

import (
	"fmt"
	"strings"
)

// importNode identifies an importable unit: a file on disk, or a
// snippet defined inside one. The file path in an importNode is
// always canonical (absolute, cleaned and symlink-resolved), so two
// textual spellings of the same file share a node regardless of the
// current working directory or path separator style.
type importNode struct {
	file        string
	snippetName string
}

// String returns the stable, canonical representation of the node,
// also used when reporting import cycles.
func (n importNode) String() string {
	if n.snippetName != "" {
		return n.file + ":" + n.snippetName
	}
	return n.file
}

// importChain is the ancestry of imports that brought a token into
// the configuration: the first entry is the top-level file and each
// following entry is a file or snippet expanded by the previous one.
// Chains are immutable values recorded per token rather than mutable
// parser state, which gives three properties at once:
//
//   - only imports actively being expanded are present, so a file
//     re-imported from a branch that already finished is expanded
//     again instead of being mistaken for a cycle (diamond imports,
//     repeated import statements, repeated glob matches);
//   - two sibling glob targets share the parent chain instead of
//     seeing each other, so siblings never form a false cycle;
//   - nothing survives a failed parse, since every Parse builds new
//     tokens and therefore new chains.
type importChain []importNode

// child returns a new chain that extends parent with next, without
// modifying the parent chain.
func childChain(parent importChain, next importNode) importChain {
	extended := make(importChain, 0, len(parent)+1)
	extended = append(extended, parent...)
	return append(extended, next)
}

// cycleError reports an error describing the closed loop when next
// is already active in chain. The reported loop starts at the first
// occurrence of next and follows the active chain back to it, in
// expansion order; it never includes imports that precede the loop
// in the configuration.
func cycleError(chain importChain, next importNode) error {
	for i, active := range chain {
		if active != next {
			continue
		}
		loop := make([]string, 0, len(chain)-i+1)
		for _, n := range chain[i:] {
			loop = append(loop, n.String())
		}
		loop = append(loop, next.String())
		return fmt.Errorf("import cycle detected: %s", strings.Join(loop, " -> "))
	}
	return nil
}

