package caddyfile

import (
	"path/filepath"

	"github.com/caddyserver/caddy/v2"
)

// canonicalFile returns the canonical representation of a file path:
// it is made absolute relative to the given path itself (never to a
// changing working directory at use site), "."/".." elements are
// cleaned away, and symlinks are resolved. When the final component
// does not exist or is part of a symlink loop, the longest existing
// parent prefix is resolved instead and the unresolved tail is
// reattached, so even error paths are stable and absolute. The
// result is never worse than an absolute, cleaned path.
func canonicalFile(name string) (string, error) {
	abs, err := caddy.FastAbs(name)
	if err != nil {
		return "", err
	}
	abs = filepath.Clean(abs)

	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		return filepath.Clean(resolved), nil
	}

	// Resolve the longest existing prefix and reattach the tail so a
	// missing target or a symlink loop on the final component still
	// has a stable canonical location to report.
	dir := filepath.Dir(abs)
	tail := filepath.Base(abs)
	for {
		resolved, err := filepath.EvalSymlinks(dir)
		if err == nil {
			return filepath.Join(resolved, tail), nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			// Nothing above resolves (e.g. a missing drive on
			// Windows); fall back to the cleaned absolute path.
			return abs, nil
		}
		tail = filepath.Join(filepath.Base(dir), tail)
		dir = parent
	}
}

