398		argTokens := p.RemainingArgsAsTokens()
399	
400		// grab all the tokens (if it exists) from within a block that follows the import
401		var blockTokens []Token
402		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
403			blockTokens = append(blockTokens, p.Token())
