package caddyfile

import (
	"strings"
	"testing"
)

func TestScratchSpecEdges(t *testing.T) {
	// arg text containing brace/quote/space inserted into an embedded placeholder
	tree := FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy \"a {x} b\"\n}\n"),
		"f.caddy":   []byte("d pre-{args[0]}-post\n"),
	}
	blocks, err := Parse("Caddyfile", tree["Caddyfile"], tree)
	if err != nil {
		t.Fatal(err)
	}
	got := flattenBlocks(blocks)
	if got[0][1] != "pre-a {x} b-post" {
		t.Fatalf("arg braces must insert literally, got %q", got[0][1])
	}

	// arg text that itself looks like a placeholder must not be re-expanded
	tree = FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy \"{args[9]}\"\n}\n"),
		"f.caddy":   []byte("d {args[0]}\n"),
	}
	blocks, err = Parse("Caddyfile", tree["Caddyfile"], tree)
	if err != nil {
		t.Fatal(err)
	}
	if flattenBlocks(blocks)[0][1] != "{args[9]}" {
		t.Fatalf("placeholder-shaped arg expanded recursively")
	}

	// backslash separators in nested relative import resolve identically
	tree = FileTree{
		"Caddyfile": []byte("import a\\f.caddy\n"),
		"a/f.caddy": []byte(":8080 {\n\timport ..\\a\\g.caddy\n}\n"),
		"a/g.caddy": []byte("ok yes\n"),
	}
	blocks, err = Parse("Caddyfile", tree["Caddyfile"], tree)
	if err != nil {
		t.Fatal(err)
	}
	if lines := flattenBlocks(blocks); lines[0][0] != "ok" || lines[0][1] != "yes" {
		t.Fatalf("separator-normalized nested import failed: %v", lines)
	}

	// failure leaves no residue: a malformed-tree parse, then a valid one
	bad := FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy a\n}\n"),
		"f.caddy":   []byte("d {args[5]}\n"),
	}
	if b, err := Parse("Caddyfile", bad["Caddyfile"], bad); err == nil || b != nil {
		t.Fatalf("expected error and nil blocks, got %v %v", b, err)
	}
	good := FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy a\n}\n"),
		"f.caddy":   []byte("d {args[0]}\n"),
	}
	blocks, err = Parse("Caddyfile", good["Caddyfile"], good)
	if err != nil {
		t.Fatalf("reparse after failure: %v", err)
	}
	if flattenBlocks(blocks)[0][1] != "a" {
		t.Fatalf("reparse contaminated by prior failure")
	}

	// undeclared placeholder in an imported snippet names file + line
	tree = FileTree{
		"Caddyfile":  []byte("import defs.caddy\n:8080 {\n\timport greet\n}\n"),
		"defs.caddy": []byte("(greet) {\n\td {args[3]}\n}\n"),
	}
	_, err = Parse("Caddyfile", tree["Caddyfile"], tree)
	if err == nil {
		t.Fatal("expected undeclared placeholder error")
	}
	if !strings.Contains(err.Error(), "defs.caddy:2") {
		t.Fatalf("error should locate defs.caddy:2, got %v", err)
	}

	// same file imported from two branches expands twice, args applied per statement
	tree = FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy one\n\timport f.caddy two\n}\n"),
		"f.caddy":   []byte("d {args[0]}\n"),
	}
	blocks, err = Parse("Caddyfile", tree["Caddyfile"], tree)
	if err != nil {
		t.Fatal(err)
	}
	lines := flattenBlocks(blocks)
	if lines[0][1] != "one" || lines[1][1] != "two" {
		t.Fatalf("repeated import expansion wrong: %v", lines)
	}

	// plain literal braces adjacent to text survive untouched
	tree = FileTree{
		"Caddyfile": []byte(":8080 {\n\timport f.caddy v\n}\n"),
		"f.caddy":   []byte("d x{{notargs}}y {host}\n"),
	}
	blocks, err = Parse("Caddyfile", tree["Caddyfile"], tree)
	if err != nil {
		t.Fatal(err)
	}
	if lines := flattenBlocks(blocks); lines[0][1] != "x{{notargs}}y" || lines[0][2] != "{host}" {
		t.Fatalf("literal braces altered: %v", lines)
	}
}

